import{at as e,it as t,t as n,yt as r}from"./chunks/framework.BXnsBMxG.js";var i=JSON.parse(`{"title":"PolarisMode (preview)","description":"Decide whether to try preview PolarisMode by weighing its immutable records and explicit editing against its current relationship and state-property limitations.","frontmatter":{"description":"Decide whether to try preview PolarisMode by weighing its immutable records and explicit editing against its current relationship and state-property limitations."},"headers":[],"relativePath":"guides/the-manual/schemas/resources/polaris-mode.md","filePath":"guides/the-manual/schemas/resources/polaris-mode.md"}`),a={name:`guides/the-manual/schemas/resources/polaris-mode.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="polarismode-preview" tabindex="-1">PolarisMode (preview) <a class="header-anchor" href="#polarismode-preview" aria-label="Permalink to “PolarisMode (preview)”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">💡 <strong>PolarisMode is not yet recommended</strong></p><p>Currently we recommend apps use <a href="./legacy-mode">LegacyMode</a>. PolarisMode is currently in preview and will become the recommendation in V6.</p></div><p>PolarisMode will become the default recommendation for new apps beginning in V6. It is currently in preview.</p><h2 id="feature-overview" tabindex="-1">Feature Overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to “Feature Overview”">​</a></h2><p>In PolarisMode:</p><ul><li>ReactiveResources are immutable (unless explicitly newly created or checked out for editing)</li><li>The mode changes how mutations are handled, local changes will only show where you want them to on the editable version of a record, while the immutable version will never show local changes.</li><li>The mode removes the API cruft Model had accumulated (references, state props, currentState, methods etc)</li><li><s>The mode enables deep reactivity for fields</s> (we have now enabled this for LegacyMode)</li><li><s>enables advanced derivations, aliasing and transformations</s> (we have now enabled this for LegacyMode)</li><li>Relationships use the <code>resource</code> and <code>collection</code> field kinds, whose values are <a href="./../../relational-data/features/resource-relationships">relationship documents</a> (<code>data</code>/<code>links</code>/<code>meta</code>) that are mutated via <code>data</code> on a checked-out record. The legacy <code>belongsTo</code>/<code>hasMany</code> kinds are supported only in <a href="./../../misc/links-mode">LinksMode</a>.</li><li><strong>[preview limitation]</strong> it has no access to reactive properties describing the resource state (such as <code>isNew</code> or <code>isDirty</code>) or utilities for working with local state like <code>rollback</code></li><li>Async relationships are not wrapped in promise proxies, and there is no autofetch.</li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};